def sum_odd(n):
    # Sum of all odd natural numbers from 1 to n.
    # There are (n + 1) // 2 odd numbers up to n, and their sum is k^2.
    if n <= 0:
        return 0
    k = (n + 1) // 2
    return k * k


def sum_in_range(l, r):
    # Sum of all odd natural numbers in the inclusive range [l, r].
    if l > r:
        return 0
    return sum_odd(r) - sum_odd(l - 1)


