def max_Product(arr):
    """
    Return the pair of elements (in their original order of appearance)
    whose product is the highest in the given array.
    """
    n = len(arr)
    if n < 2:
        raise ValueError("Array must contain at least two elements")

    x, y = arr[0], arr[1]
    for i in range(n):
        for j in range(i + 1, n):
            if arr[i] * arr[j] > x * y:
                x, y = arr[i], arr[j]
    return (x, y)


if __name__ == "__main__":
    assert max_Product([1, 2, 3, 4, 7, 0, 8, 4]) == (7, 8)
    assert max_Product([0, -1, -2, -4, 5, 0, -6]) == (-4, -6)
    assert max_Product([1, 2, 3]) == (2, 3)
    print("All tests passed!")
```

This runs in O(n²) time. A faster approach would find the two largest and two smallest values, since two large negatives can also give the top product. That approach doesn't keep the original order of the pair, so the simple loop is used here.
